/*
 * A098217  Cototients of terms from A098216. By definitions these cototient
 *          values are decimal repdigits.
 * https://oeis.org/A098217
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n-th cototient of m (m – φ(m)) that is a decimal
 *            repdigit. The sequence is generated by scanning m = 1, 2, 3, …
 *            and storing values m – φ(m) whenever the result consists of
 *            identical decimal digits. The function keeps a dynamic cache so
 *            that calls to `a` with arbitrary indices are answ...
 * Range:     u8 n <= 30, u16 n <= 67, u32 n <= 67, u64 n <= 67, u128 n <= 67,
 *            big any n
 * Helpers:   calc_phi
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/calc_phi.h"

/* Test whether x is a decimal repdigit (all digits equal). */
static bool is_repdigit(seq_t x)
{
    if (x == 0)
        return true;            /* 0 is regarded as a repdigit */
    if (x == 1)
        return false;           /* 1 has a single digit, not repeated */
    unsigned int last = (unsigned int)(x % 10);
    seq_t t = x / 10;
    while (t > 0) {
        if ((unsigned int)(t % 10) != last)
            return false;
        t /= 10;
    }
    return true;
}

/* Cache of cototient repdigits found so far. */
static seq_t *cache      = NULL;   /* array data */
static size_t cache_cap  = 0;      /* allocated capacity */
static size_t cache_len  = 0;      /* number of stored elements   */
static uint64_t processed = 0;     /* largest m that has been examined */

/* Return the n‑th element of the OEIS A098217 sequence. */
seq_t a(idx_t n)
{
    if (n < 1)
        return 0;                /* undefined below offset 1 */

    /* Extend the cache until it contains at least n values. */
    while (cache_len < (size_t)n) {
        uint64_t m = processed + 1;               /* m to test */
        seq_t  mseq = (seq_t)m;                   /* cast to seq_t */
        seq_t phi  = calc_phi(mseq);              /* φ(m)       */
        seq_t cot  = mseq - phi;                  /* cototient  */

        if (is_repdigit(cot)) {
            /* Grow the cache if necessary. */
            if (cache_len == cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 16;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp) {
                    free(cache);
                    exit(EXIT_FAILURE);
                }
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = cot;              /* store result */
        }

        processed = m;
    }

    return cache[n - 1];          /* zero‑based index in the cache */
}
